package com.runemargin.sync;

final class OfferSnapshot
{
    final int itemId;
    final long offerPrice;
    final int totalQuantity;
    final int quantitySold;
    final long spent;
    final boolean buy;
    final String state;

    OfferSnapshot(
        int itemId,
        long offerPrice,
        int totalQuantity,
        int quantitySold,
        long spent,
        boolean buy,
        String state)
    {
        this.itemId = itemId;
        this.offerPrice = offerPrice;
        this.totalQuantity = totalQuantity;
        this.quantitySold = quantitySold;
        this.spent = spent;
        this.buy = buy;
        this.state = state;
    }

    boolean sameOfferAs(OfferSnapshot other)
    {
        return other != null
            && itemId == other.itemId
            && offerPrice == other.offerPrice
            && totalQuantity == other.totalQuantity
            && buy == other.buy;
    }
}

package com.runemargin.sync;

import com.google.gson.Gson;
import com.google.inject.Inject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.UUID;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.RuneLite;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
    name = "RuneMargin Sync",
    description = "Records exact Grand Exchange fill totals locally for RuneMargin Tracker",
    tags = {"grand exchange", "ge", "prices", "flipping", "tracker", "runemargin"}
)
public class RuneMarginSyncPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(RuneMarginSyncPlugin.class);
    private static final int SLOT_COUNT = 8;
    private static final String DIRECTORY_NAME = "runemargin-sync";
    private static final String HISTORY_FILE_NAME = "trades-v1.jsonl";

    @Inject
    private Gson gson;

    private final OfferSnapshot[] previousOffers = new OfferSnapshot[SLOT_COUNT];
    private Path historyFile;

    @Override
    protected void startUp()
    {
        Path directory = RuneLite.RUNELITE_DIR.toPath().resolve(DIRECTORY_NAME);
        historyFile = directory.resolve(HISTORY_FILE_NAME);
        try
        {
            Files.createDirectories(directory);
        }
        catch (IOException exception)
        {
            LOG.warn("Unable to create the RuneMargin Sync directory", exception);
        }
    }

    @Override
    protected void shutDown()
    {
        for (int slot = 0; slot < previousOffers.length; slot++)
        {
            previousOffers[slot] = null;
        }
    }

    @Subscribe
    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
    {
        int slot = event.getSlot();
        if (slot < 0 || slot >= SLOT_COUNT)
        {
            return;
        }

        GrandExchangeOffer offer = event.getOffer();
        if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
        {
            previousOffers[slot] = null;
            return;
        }

        OfferSnapshot current = snapshot(offer);
        TradeDelta delta = TradeDeltaDetector.detect(previousOffers[slot], current);
        previousOffers[slot] = current;
        if (delta == null)
        {
            return;
        }

        long averagePrice = Math.round((double) delta.gp / delta.quantity);
        TradeFillRecord record = new TradeFillRecord(
            UUID.randomUUID().toString(),
            Instant.now().toString(),
            current.itemId,
            current.buy,
            delta.quantity,
            delta.gp,
            averagePrice,
            current.offerPrice,
            slot,
            current.quantitySold,
            current.totalQuantity,
            current.state);
        append(record);
    }

    private static OfferSnapshot snapshot(GrandExchangeOffer offer)
    {
        GrandExchangeOfferState state = offer.getState();
        boolean buy = state == GrandExchangeOfferState.BUYING
            || state == GrandExchangeOfferState.BOUGHT
            || state == GrandExchangeOfferState.CANCELLED_BUY;
        return new OfferSnapshot(
            offer.getItemId(),
            offer.getPrice(),
            offer.getTotalQuantity(),
            offer.getQuantitySold(),
            offer.getSpent(),
            buy,
            state.name());
    }

    private void append(TradeFillRecord record)
    {
        if (historyFile == null)
        {
            return;
        }

        String line = gson.toJson(record) + System.lineSeparator();
        try
        {
            Files.write(
                historyFile,
                line.getBytes(StandardCharsets.UTF_8),
                StandardOpenOption.CREATE,
                StandardOpenOption.WRITE,
                StandardOpenOption.APPEND);
        }
        catch (IOException exception)
        {
            LOG.warn("Unable to append a RuneMargin Grand Exchange fill", exception);
        }
    }
}

package com.runemargin.sync;

final class TradeDelta
{
    final int quantity;
    final long gp;

    TradeDelta(int quantity, long gp)
    {
        this.quantity = quantity;
        this.gp = gp;
    }
}

package com.runemargin.sync;

final class TradeDeltaDetector
{
    private TradeDeltaDetector()
    {
    }

    static TradeDelta detect(OfferSnapshot previous, OfferSnapshot current)
    {
        if (previous == null || current == null || !current.sameOfferAs(previous))
        {
            return null;
        }

        int quantity = current.quantitySold - previous.quantitySold;
        long gp = current.spent - previous.spent;
        return quantity > 0 && gp > 0 ? new TradeDelta(quantity, gp) : null;
    }
}

package com.runemargin.sync;

final class TradeFillRecord
{
    final int schemaVersion = 1;
    final String eventId;
    final String timestampUtc;
    final int itemId;
    final boolean buy;
    final int deltaQuantity;
    final long deltaGp;
    final long averagePrice;
    final long offerPrice;
    final int slot;
    final int cumulativeQuantity;
    final int totalQuantity;
    final String state;

    TradeFillRecord(
        String eventId,
        String timestampUtc,
        int itemId,
        boolean buy,
        int deltaQuantity,
        long deltaGp,
        long averagePrice,
        long offerPrice,
        int slot,
        int cumulativeQuantity,
        int totalQuantity,
        String state)
    {
        this.eventId = eventId;
        this.timestampUtc = timestampUtc;
        this.itemId = itemId;
        this.buy = buy;
        this.deltaQuantity = deltaQuantity;
        this.deltaGp = deltaGp;
        this.averagePrice = averagePrice;
        this.offerPrice = offerPrice;
        this.slot = slot;
        this.cumulativeQuantity = cumulativeQuantity;
        this.totalQuantity = totalQuantity;
        this.state = state;
    }
}

package com.runemargin.sync;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RuneMarginSyncPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(RuneMarginSyncPlugin.class);
        RuneLite.main(args);
    }
}

package com.runemargin.sync;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class TradeDeltaDetectorTest
{
    @Test
    public void detectsPartialFillDelta()
    {
        OfferSnapshot before = offer(0, 0);
        OfferSnapshot after = offer(25, 25_125);
        TradeDelta delta = TradeDeltaDetector.detect(before, after);

        assertEquals(25, delta.quantity);
        assertEquals(25_125, delta.gp);
    }

    @Test
    public void ignoresInitialSnapshot()
    {
        assertNull(TradeDeltaDetector.detect(null, offer(25, 25_125)));
    }

    @Test
    public void ignoresDuplicateEvent()
    {
        OfferSnapshot snapshot = offer(25, 25_125);
        assertNull(TradeDeltaDetector.detect(snapshot, snapshot));
    }

    @Test
    public void ignoresReusedSlotForDifferentOffer()
    {
        OfferSnapshot previous = offer(25, 25_125);
        OfferSnapshot replacement = new OfferSnapshot(556, 120, 500, 10, 1_200, true, "BUYING");
        assertNull(TradeDeltaDetector.detect(previous, replacement));
    }

    @Test
    public void supportsGpTotalsLargerThan32BitIntegers()
    {
        OfferSnapshot before = offer(1, 2_500_000_000L);
        OfferSnapshot after = offer(2, 5_000_000_000L);
        TradeDelta delta = TradeDeltaDetector.detect(before, after);

        assertEquals(1, delta.quantity);
        assertEquals(2_500_000_000L, delta.gp);
    }

    private static OfferSnapshot offer(int quantitySold, long spent)
    {
        return new OfferSnapshot(561, 1005, 100, quantitySold, spent, true, "BUYING");
    }
}
